#include <map>
#include <vector>

int main() {
    std::map<int, char> m;
    m.insert({10, 'a'});
    auto it = m.begin(); // Iterator points to (10, 'a')

    // Efficient O(1) insertion: 11 follows 10
    it = m.insert(it, {11, 'b'}); 

    // Inefficient, O(log N) insertion: hint 'it' is now (11, 'b'), 
    // but 5 should precede 10.
    m.insert(it, {5, 'c'}); 
}
